function allTasks(){const rows=workflowTasks();return T.heading('Задачи агентства','Все ближайшие действия в одном списке',`<button class="btn primary" data-go="tasks">${I('plus',15)} Открыть план свадьбы</button>`)+(T.state.mode==='empty'?T.empty('Задач пока нет','Создайте первую свадьбу или откройте план подготовки.',B('Открыть план свадьбы','ag-to-tasks','primary')):`<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Задача</th><th>Свадьба</th><th>Срок</th><th>Ответственный</th><th>Состояние</th></tr></thead><tbody>${rows.slice(0,9).map(t=>`<tr class="clickable-row" data-action="ag-task-open" data-id="${t.id}"><td class="row-main">${E(t.title)}</td><td>${E((T.data.projects.find(p=>p.id===t.projectId)||T.project()).name)}</td><td>${E(t.due||'—')}</td><td>${E(t.assignee||'—')}</td><td>${T.badge(t.status==='done'?'Выполнено':t.status==='doing'?'В работе':t.status==='skipped'?'Не требуется':'Запланировано',t.status==='done'?'green':t.status==='doing'?'rose':t.status==='skipped'?'gray':'amber')}</td></tr>`).join('')}</tbody></table></div>`)}
function vendorForm(v){formModal(v?'Изменить подрядчика':'Новый подрядчик',F('Имя / название',IN('name',v?.name||''))+F('Категория',SEL('category',['Фотограф','Декор и флористика','Ведущий','Кейтеринг','Музыка','Стилист'],v?.category||'Фотограф'))+F('Стоимость от, ₽',IN('price',v?.price||'','','number'))+F('Контакт',IN('contact',v?.contact||'','','email'))+F('Описание','<textarea name="description">'+E(v?.description||'')+'</textarea>',true),f=>{if(v)Object.assign(v,f);else T.data.vendors.push({id:'v'+Date.now(),...f,status:'В подборке',initials:f.name.split(' ').map(x=>x[0]).slice(0,2).join('')});T.state.mode='filled'})}
function expenseForm(x){formModal(x?'Статья сметы':'Новый расход',F('Название',IN('name',x?.name||''))+F('Подрядчик',IN('vendor',x?.vendor||''))+F('Плановая сумма',IN('total',x?.total||'','','number'))+F('Уже оплачено',IN('paid',x?.paid||'0','','number'))+F('Срок',IN('date',x?.date||'15 сентября'))+F('Категория',SEL('category',['Площадка','Декор','Фото и видео','Программа','Банкет'],x?.category||'Площадка')),f=>{f.total=Number(f.total);f.paid=Number(f.paid);f.status=f.total===f.paid?'Оплачено':'Частично оплачено';if(x)Object.assign(x,f);else T.data.expenses.push(f);T.state.mode='filled'})}
